-- LOCAL PRO ONLY. Owner verifies existing canonical objects; no storage writes,
-- deletes, actor impersonation, original receipt changes or notifications.
begin;
create table if not exists public.pro_daily_log_file_reconcile_actions(
 owner_id uuid not null references profiles(id) on delete cascade,action_id uuid not null,work_id text not null,log_id uuid not null,file_id uuid not null,
 input jsonb not null,baseline jsonb not null,original_actor_id uuid not null,original_actor_name text not null,original_action_id uuid,original_grant_id uuid,original_generation uuid,
 requested_name text not null,reserved_at timestamptz not null default now(),reason text check(reason in('missing_object','mismatch','unavailable')),outcome text check(outcome in('completed','already_ready')),result jsonb,
 primary key(owner_id,action_id),foreign key(owner_id,work_id,log_id,file_id) references pro_daily_log_files(owner_id,work_id,log_id,id) on delete cascade,
 check((outcome is null)=(result is null)),check(result is null or reason is null)
);
create unique index if not exists pro_daily_file_one_retirement on pro_daily_log_file_reconcile_actions(file_id) where outcome='completed';
create index if not exists pro_daily_file_retired_actor_action on pro_daily_log_file_reconcile_actions(original_actor_id,original_action_id) where outcome='completed';
create index if not exists pro_daily_file_reconcile_history on pro_daily_log_file_reconcile_actions(owner_id,work_id,log_id,reserved_at desc,action_id desc);
create table if not exists public.pro_daily_log_file_reconcile_events(owner_id uuid not null,action_id uuid not null,kind text not null check(kind in('reserved','confirmed','missing_object','mismatch','unavailable')),actor_id uuid not null,actor_name text not null,at timestamptz not null default now(),primary key(owner_id,action_id,kind),foreign key(owner_id,action_id) references pro_daily_log_file_reconcile_actions(owner_id,action_id) on delete cascade);
create or replace function public.pro_daily_file_reconcile_json(p_action public.pro_daily_log_file_reconcile_actions) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$select jsonb_build_object('input',p_action.input,'baseline',p_action.baseline,'phase',case when p_action.result is null then 'pending' else 'confirmed' end,'result',p_action.result,'reservedAt',p_action.reserved_at,'reason',p_action.reason)$$;
create or replace function public.pro_daily_file_reconcile_owner(p_actor uuid,p_work text,p_log uuid,p_write boolean default false) returns void language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin perform pro_work_schedule_owner(p_actor,p_work);if not exists(select 1 from pro_daily_logs where owner_id=p_actor and work_id=p_work and id=p_log) then raise exception 'Daily log unavailable' using errcode='42501';end if;if p_write and exists(select 1 from pro_daily_logs where owner_id=p_actor and work_id=p_work and id=p_log and archived) then raise exception 'Restore the daily log first' using errcode='40001';end if;end $$;
-- Permanent retirement is scoped to the original uploader/operation, not the file
-- author metadata. Historical public downloads keep their independent audience ACL.
create or replace function public.pro_daily_file_retirement_guard(p_actor uuid,p_action uuid,p_file uuid default null) returns void language plpgsql stable security invoker set search_path=public,pg_temp as $$begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if exists(select 1 from pro_daily_log_file_reconcile_actions where outcome='completed' and original_actor_id=p_actor and(original_action_id=p_action or p_file is not null and file_id=p_file)) then raise exception 'The owner completed this pending upload' using errcode='42501';end if;
 if exists(select 1 from pro_daily_log_file_reconcile_actions where owner_id=p_actor and action_id=p_action) then raise exception 'Action belongs to file reconciliation' using errcode='22023';end if;
end $$;
create or replace function public.pro_daily_file_reconcile_reserve(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;wid text;lid uuid;fid uuid;keys text[];a pro_daily_log_file_reconcile_actions;f pro_daily_log_files;original_aid uuid;original_actor uuid;begin
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid reconciliation' using errcode='22023';end if;select array_agg(key order by key) into keys from jsonb_object_keys(p_input)key;
 if keys is distinct from array['action','actionId','fileId','logId','sha256','workId'] or p_input->>'action' is distinct from 'reconcile' or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'fileId') is distinct from 'string' or jsonb_typeof(p_input->'workId') is distinct from 'string' or jsonb_typeof(p_input->'logId') is distinct from 'string' or not coalesce((p_input->>'sha256')~'^[a-f0-9]{64}$',false) then raise exception 'Invalid reconciliation fields' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;wid:=p_input->>'workId';lid:=(p_input->>'logId')::uuid;fid:=(p_input->>'fileId')::uuid;perform pro_daily_file_reconcile_owner(p_actor,wid,lid);
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-reconcile:'||p_actor::text||':'||aid::text,0));
 select * into a from pro_daily_log_file_reconcile_actions where owner_id=p_actor and action_id=aid;if found then if a.input is distinct from p_input then raise exception 'Reconciliation identity reused' using errcode='22023';end if;return jsonb_build_object('attempt',pro_daily_file_reconcile_json(a),'objectPath',a.owner_id::text||'/'||a.file_id::text||case when a.baseline->>'mimeType'='application/pdf' then '.pdf' else '.jpg' end);end if;
 if exists(select 1 from pro_daily_log_file_actions where actor_id=p_actor and action_id=aid) or exists(select 1 from pro_daily_log_actions where actor_id=p_actor and action_id=aid) then raise exception 'Action identity already used' using errcode='22023';end if;
 select * into f from pro_daily_log_files where owner_id=p_actor and work_id=wid and log_id=lid and id=fid;if not found then raise exception 'File unavailable' using errcode='42501';end if;if f.sha256<>p_input->>'sha256' then raise exception 'File hash changed' using errcode='40001';end if;
 original_actor:=f.created_by;select action_id into original_aid from pro_daily_log_file_actions where actor_id=original_actor and owner_id=p_actor and work_id=wid and log_id=lid and input->>'fileId'=fid::text and input->>'action' in('upload','copy') order by at,action_id limit 1;
 if original_aid is not null then perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-action:'||original_actor::text||':'||original_aid::text,0));end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||p_actor::text||':'||wid,0));if f.created_grant_id is not null then perform 1 from pro_team_grants where id=f.created_grant_id for share;end if;
 perform pro_daily_file_reconcile_owner(p_actor,wid,lid,true);select * into f from pro_daily_log_files where owner_id=p_actor and work_id=wid and log_id=lid and id=fid for update;if not found or f.sha256<>p_input->>'sha256' then raise exception 'File changed' using errcode='40001';end if;
 insert into pro_daily_log_file_reconcile_actions(owner_id,action_id,work_id,log_id,file_id,input,baseline,original_actor_id,original_actor_name,original_action_id,original_grant_id,original_generation,requested_name) values(p_actor,aid,wid,lid,fid,p_input,pro_daily_log_file_json(f),f.created_by,f.created_by_name,original_aid,f.created_grant_id,f.source_invite_id,pro_team_name(p_actor)) returning * into a;
 insert into pro_daily_log_file_reconcile_events(owner_id,action_id,kind,actor_id,actor_name) values(p_actor,aid,'reserved',p_actor,pro_team_name(p_actor));perform pro_daily_file_reconcile_owner(p_actor,wid,lid,true);
 return jsonb_build_object('attempt',pro_daily_file_reconcile_json(a),'objectPath',f.object_path);
end $$;
create or replace function public.pro_daily_file_reconcile_note(p_actor uuid,p_action uuid,p_reason text) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare a pro_daily_log_file_reconcile_actions;begin
 if p_reason is null or p_reason not in('missing_object','mismatch','unavailable') then raise exception 'Invalid pending reason' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-reconcile:'||p_actor::text||':'||p_action::text,0));select * into a from pro_daily_log_file_reconcile_actions where owner_id=p_actor and action_id=p_action for update;if not found then raise exception 'Reconciliation unavailable' using errcode='42501';end if;perform pro_daily_file_reconcile_owner(p_actor,a.work_id,a.log_id);
 if a.result is null then update pro_daily_log_file_reconcile_actions set reason=p_reason where owner_id=p_actor and action_id=p_action returning * into a;insert into pro_daily_log_file_reconcile_events(owner_id,action_id,kind,actor_id,actor_name) values(p_actor,p_action,p_reason,p_actor,pro_team_name(p_actor)) on conflict(owner_id,action_id,kind) do nothing;end if;return pro_daily_file_reconcile_json(a);
end $$;
create or replace function public.pro_daily_file_reconcile_finish(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare a pro_daily_log_file_reconcile_actions;f pro_daily_log_files;head integer;outcome_text text;answer jsonb;begin
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-reconcile:'||p_actor::text||':'||p_action::text,0));select * into a from pro_daily_log_file_reconcile_actions where owner_id=p_actor and action_id=p_action;if not found then raise exception 'Reconciliation unavailable' using errcode='42501';end if;perform pro_daily_file_reconcile_owner(p_actor,a.work_id,a.log_id);if a.result is not null then return pro_daily_file_reconcile_json(a);end if;
 if a.original_action_id is not null then perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-action:'||a.original_actor_id::text||':'||a.original_action_id::text,0));end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||p_actor::text||':'||a.work_id,0));if a.original_grant_id is not null then perform 1 from pro_team_grants where id=a.original_grant_id for share;end if;
 perform pro_daily_file_reconcile_owner(p_actor,a.work_id,a.log_id,true);select * into f from pro_daily_log_files where owner_id=p_actor and work_id=a.work_id and log_id=a.log_id and id=a.file_id for update;if not found or f.sha256<>a.input->>'sha256' then raise exception 'File changed' using errcode='40001';end if;
 if f.ready then outcome_text:='already_ready';select revision into head from pro_daily_log_file_heads where owner_id=p_actor and work_id=a.work_id and log_id=a.log_id;head:=coalesce(head,f.ready_revision);
 else outcome_text:='completed';head:=pro_daily_log_file_head_advance(p_actor,a.work_id,a.log_id);update pro_daily_log_files set ready=true,ready_revision=head where id=a.file_id returning * into f;end if;
 -- Required final reauthorization AFTER any head-row wait and file transition.
 -- A concurrent membership revocation rolls back ready/head/retirement/audit.
 perform pro_daily_file_reconcile_owner(p_actor,a.work_id,a.log_id,true);
 answer:=jsonb_build_object('action','reconcile','outcome',outcome_text,'file',pro_daily_log_file_json(f),'revision',head,'verifiedBy',jsonb_build_object('id',p_actor,'name',pro_team_name(p_actor),'at',now()));
 update pro_daily_log_file_reconcile_actions set reason=null,outcome=outcome_text,result=answer where owner_id=p_actor and action_id=p_action returning * into a;
 insert into pro_daily_log_file_reconcile_events(owner_id,action_id,kind,actor_id,actor_name) values(p_actor,p_action,'confirmed',p_actor,pro_team_name(p_actor));perform pro_daily_file_reconcile_owner(p_actor,a.work_id,a.log_id,true);return pro_daily_file_reconcile_json(a);
end $$;
create or replace function public.pro_daily_file_reconcile_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare a pro_daily_log_file_reconcile_actions;begin
 if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;select * into a from pro_daily_log_file_reconcile_actions where owner_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('attempt',null);end if;perform pro_daily_file_reconcile_owner(p_actor,a.work_id,a.log_id);return jsonb_build_object('attempt',pro_daily_file_reconcile_json(a));end $$;
create or replace function public.pro_daily_file_reconcile_history(p_actor uuid,p_work text,p_log uuid,p_after uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare items jsonb;cursor_at timestamptz;cursor_id uuid;begin
 perform pro_daily_file_reconcile_owner(p_actor,p_work,p_log);
 if p_after is not null then select reserved_at into cursor_at from pro_daily_log_file_reconcile_actions where owner_id=p_actor and work_id=p_work and log_id=p_log and action_id=p_after;if not found then raise exception 'History cursor changed' using errcode='40001';end if;end if;
 select coalesce(jsonb_agg(jsonb_build_object('actionId',a.action_id,'fileId',a.file_id,'fileName',a.baseline->>'name','originalActorId',a.original_actor_id,'originalActorName',a.original_actor_name,'phase',case when a.result is null then 'pending' else 'confirmed' end,'reason',a.reason,'requestedBy',jsonb_build_object('id',a.owner_id,'name',a.requested_name),'reservedAt',a.reserved_at,'outcome',a.outcome,'verifiedAt',a.result->'verifiedBy'->'at','verifiedByName',a.result->'verifiedBy'->>'name') order by a.reserved_at desc,a.action_id desc),'[]'::jsonb) into items from(select * from pro_daily_log_file_reconcile_actions where owner_id=p_actor and work_id=p_work and log_id=p_log and(p_after is null or(reserved_at,action_id)<(cursor_at,p_after)) order by reserved_at desc,action_id desc limit 21)a;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'actionId')::uuid;items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',cursor_id);end $$;
-- Guarded facades share the ORIGINAL operation advisory. Retirement cannot race
-- between the guard and old reserve/ready execution; old SQL remains unchanged.
create or replace function public.pro_daily_log_file_reserve_guarded(p_actor uuid,p_input jsonb,p_input_hash text) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare aid uuid;begin aid:=(p_input->>'actionId')::uuid;perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-action:'||p_actor::text||':'||aid::text,0));perform pro_daily_file_retirement_guard(p_actor,aid,(p_input->>'fileId')::uuid);return pro_daily_log_file_reserve(p_actor,p_input,p_input_hash);end $$;
create or replace function public.pro_daily_log_file_pending_guarded(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$begin perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-action:'||p_actor::text||':'||p_action::text,0));perform pro_daily_file_retirement_guard(p_actor,p_action);return pro_daily_log_file_pending(p_actor,p_action);end $$;
create or replace function public.pro_daily_log_file_ready_guarded(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$begin perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-action:'||p_actor::text||':'||p_action::text,0));perform pro_daily_file_retirement_guard(p_actor,p_action);return pro_daily_log_file_ready(p_actor,p_action);end $$;
create or replace function public.pro_daily_log_file_action_read_guarded(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$begin perform pro_daily_file_retirement_guard(p_actor,p_action);return pro_daily_log_file_action_read(p_actor,p_action);end $$;
create or replace function public.pro_daily_file_reconcile_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin
 if old.result is not null or(to_jsonb(new)-array['reason','outcome','result']) is distinct from(to_jsonb(old)-array['reason','outcome','result']) or new.result is null and new.outcome is not null or new.result is not null and(new.outcome is null or new.reason is not null) then raise exception 'Reconciliation history is immutable' using errcode='23514';end if;return new;end $$;
drop trigger if exists pro_daily_file_reconcile_immutable on pro_daily_log_file_reconcile_actions;create trigger pro_daily_file_reconcile_immutable before update on pro_daily_log_file_reconcile_actions for each row execute function pro_daily_file_reconcile_immutable();
drop trigger if exists pro_daily_file_reconcile_event_immutable on pro_daily_log_file_reconcile_events;create trigger pro_daily_file_reconcile_event_immutable before update on pro_daily_log_file_reconcile_events for each row execute function pro_team_append_only();
do $$declare tab text;f record;begin foreach tab in array array['pro_daily_log_file_reconcile_actions','pro_daily_log_file_reconcile_events'] loop execute format('alter table public.%I enable row level security',tab);execute format('revoke all on public.%I from public,anon,authenticated',tab);execute format('grant all on public.%I to service_role',tab);end loop;
 for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('pro_daily_file_reconcile_json','pro_daily_file_reconcile_owner','pro_daily_file_retirement_guard','pro_daily_file_reconcile_reserve','pro_daily_file_reconcile_note','pro_daily_file_reconcile_finish','pro_daily_file_reconcile_read','pro_daily_file_reconcile_history','pro_daily_log_file_reserve_guarded','pro_daily_log_file_pending_guarded','pro_daily_log_file_ready_guarded','pro_daily_log_file_action_read_guarded','pro_daily_file_reconcile_immutable') loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
commit;
